import{_ as i,o as e,c as o,a2 as l}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Unidad Curricular: Proyecto Socio Tecnológico II","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/Contenido_Programatico.md","filePath":"materias/Proyecto_Sociotecnologico_II/Contenido_Programatico.md"}'),r={name:"materias/Proyecto_Sociotecnologico_II/Contenido_Programatico.md"};function t(n,a,c,s,d,u){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="unidad-curricular-proyecto-socio-tecnologico-ii" tabindex="-1">Unidad Curricular: Proyecto Socio Tecnológico II <a class="header-anchor" href="#unidad-curricular-proyecto-socio-tecnologico-ii" aria-label="Permalink to &quot;Unidad Curricular: Proyecto Socio Tecnológico II&quot;">​</a></h1><p><strong>Trayecto:</strong> II <strong>Código:</strong> PTP239 <strong>Unidades Crédito:</strong> 9 <strong>Duración:</strong> 3 trimestres <strong>Tipo:</strong> Proyecto</p><table tabindex="0"><thead><tr><th style="text-align:left;">Densidad Semanal</th><th style="text-align:left;">Hora Acad.</th><th style="text-align:left;">HTEA</th><th style="text-align:left;">HTEI</th><th style="text-align:left;">THTE</th></tr></thead><tbody><tr><td style="text-align:left;">60&#39;</td><td style="text-align:left;">6</td><td style="text-align:left;">0.5</td><td style="text-align:left;">6.5</td><td style="text-align:left;">6.5</td></tr></tbody></table><hr><h2 id="saberes-contenido-analitico" tabindex="-1">SABERES (Contenido Analítico) <a class="header-anchor" href="#saberes-contenido-analitico" aria-label="Permalink to &quot;SABERES (Contenido Analítico)&quot;">​</a></h2><p><strong>Unidad 1: Problema o situación que requiera desarrollo de aplicaciones informáticas</strong></p><ul><li>Orientaciones para el desarrollo de proyectos en el área de Hardware y Software, según el alcance del PSTII.</li><li>Levantamiento de Información.</li><li>Diagnóstico Participativo.</li><li>Fases del Diagnóstico Participativo: <ul><li>Determinar el problema.</li><li>Elaborar el Plan Diagnóstico.</li><li>Recopilar la información.</li><li>Procesar la Información.</li><li>Socializar los Resultados.</li></ul></li></ul><p><strong>Unidad 2: Planteamiento del proyecto sociotecnológico</strong></p><ul><li>Definición del problema, objetivos y alcance.</li></ul><p><strong>Unidad 3: Planificación de Proyectos</strong></p><ul><li>Estudio de Factibilidad.</li><li>Cronograma de actividades.</li></ul><p><strong>Unidad 4: Ejecución del Proyecto Sociotecnológico</strong></p><ul><li>Selección de la metodología a utilizar.</li><li>Aplicación de la metodología seleccionada.</li><li>Diseño y desarrollo de la aplicación informática, acorde al alcance del proyecto.</li></ul><p><strong>Unidad 5: Pruebas</strong></p><ul><li>Planificación y aplicación de las pruebas.</li><li>Corrección de errores críticos.</li><li>Recomendaciones de mejoras.</li></ul><p><strong>Unidad 6: Presentación del Prototipo</strong></p><ul><li>Mostrar el módulo funcional realizado.</li></ul><p><strong>Unidad 7: Implementación</strong></p><p><strong>Unidad 8: Manuales e informe final</strong></p><ul><li>Desarrollo de los manuales requeridos en el proyecto y entrenamiento a usuarios.</li><li>Desarrollo del informe final.</li></ul><hr><h2 id="estrategias" tabindex="-1">ESTRATEGIAS <a class="header-anchor" href="#estrategias" aria-label="Permalink to &quot;ESTRATEGIAS&quot;">​</a></h2><ul><li>Los actores deben abordar la comunidad para conocerla, describirla y detectar necesidades.</li><li>Realizar talleres, conversatorios o charlas con invitados especiales de organismos que apoyen la ejecución de proyectos.</li><li>Investigar sobre los proyectos informáticos locales, regionales y nacionales y los organismos que apoyan la ejecución de los mismos.</li><li>Plantear alternativas de soluciones ante situaciones y problemas reales, relacionados con soluciones informáticas.</li></ul><hr><h2 id="recursos" tabindex="-1">RECURSOS <a class="header-anchor" href="#recursos" aria-label="Permalink to &quot;RECURSOS&quot;">​</a></h2><ul><li>Pizarra magnética</li><li>Marcadores</li><li>Material Educativo Computarizado: Material Instructivo, Software</li><li>Computador</li><li>Proyector Multimedia</li><li>Plataforma Tecnológica</li><li>Aula de encuentros, aula taller, laboratorios.</li></ul><hr><h2 id="evaluacion" tabindex="-1">EVALUACIÓN <a class="header-anchor" href="#evaluacion" aria-label="Permalink to &quot;EVALUACIÓN&quot;">​</a></h2><p>Entrega y presentación del Informe: indicándose las actividades y fases desarrolladas. Coevaluación y Autoevaluación.</p><p><strong>Productos Entregables:</strong></p><ul><li><strong>1er Informe de avance:</strong><ul><li>Problema a abordar (Análisis de Involucrados, Árbol del Problema).</li><li>Objetivos del proyecto (Árbol de Objetivos).</li><li>Informe de Visitas a la comunidad.</li></ul></li><li><em>Afinar 1er Informe de avances.</em></li><li><strong>2do Informe de avance:</strong><ul><li>Descripción de la ejecución de la solución informática seleccionada (hardware o software).</li><li>Informe de Visitas a la comunidad.</li></ul></li><li><em>Afinar 2do informe de avance.</em></li><li><strong>Entrega y presentación del proyecto sociotecnológico final:</strong><ul><li>Manuales de Usuarios y de sistema.</li><li>Informe de Visitas a la comunidad.</li></ul></li></ul><hr><h2 id="referencias" tabindex="-1">REFERENCIAS <a class="header-anchor" href="#referencias" aria-label="Permalink to &quot;REFERENCIAS&quot;">​</a></h2><ul><li>Cordoba Padilla M. (2006). Formulación y Evaluación de Proyectos. Ecoe.</li><li>Miranda Juan José (2005). Gestión de Proyectos. MM editores.</li><li>Villarroel Mariel &amp; Esté Pedro (2010). Los Proyectos de Participación Comunitaria y su práctica social. 2da. Edición. Valencia-Venezuela.</li><li>Villarroel, E. y Esté, P. (2008). Los Proyectos de Participación Comunitaria y su Práctica Social. Manual de Ejecución para Estudiantes Universitarios. Valencia – Venezuela.</li><li>Hernández, R., Fernández, C., Collado, P., Baptista, L. (2006). Metodología de la Investigación. 4ta Ed. Mc Graw Hill. México.</li><li>Crespo, M. (2009). Guía de diseño de proyectos sociales comunitarios bajo el enfoque del marco lógico. Conceptos esenciales y aplicaciones. Caracas – Venezuela.</li><li>Sarmiento, M. y Abreu, M. (2009). Cómo Diseñar Proyectos Comunitarios (Bajo el enfoque del Marco Lógico). Guía teórico-práctica. Ministerio del Poder Popular para Ciencia, Tecnología e Industrias Intermedias. Fundacite Zulia. Venezuela.</li><li>Ortegón, E., Pacheco, J. y Prieto, A. (2005). Metodología del Marco Lógico para la Planificación, el Seguimiento y la Evaluación de Proyectos y Programas. CEPAL. Serie Manuales. Chile.</li><li>Instituto Politécnico Nacional (2002). Metodología para el Análisis FODA. Dirección de Planeación y Organización. México.</li><li>Plasencia, Z. (2008). Introducción a la Informática. Editorial Anaya Multimedia.</li><li>Prieto, A., Lloris, A. y Torres, J. (2006) Introducción a la Informática. Editorial McGrawHill.</li><li>Eckois, Steve (1986). Como diseñar y Desarrollar Sistemas de Información. 1a. Ed. Venezuela.</li><li>Gomez, Guillermo. (1998). Sistemas Administrativos. 1a. Ed. México.</li><li>Kendall &amp; Kendall (2005). Análisis y diseño de sistemas. (6ª ed.). México: Pearson.</li><li>Pressman, R. (2002). Ingeniería de software. Un enfoque práctico. (5ª ed.). España: McGraw-Hill Interamericana de España, S.A.</li><li>Ruble, D. (1998). Análisis y Diseño Práctico de Sistemas. México: Prentice Hall.</li><li>Sampieri, Roberto y otros. Metodología de la Investigación. Ed. McGraw-hill, 1996.</li><li>Yourdon, E. (1993). Análisis Estructurado Moderno. (1ª ed.). México: Prentice Hall.</li></ul>',34)])])}const p=i(r,[["render",t]]);export{g as __pageData,p as default};
